const LESSONS = {"en":{"foundations":{"title":"Stock Market Foundations","level":"beginner","time":"6 lessons","summary":"What a share is, how exchanges work, and how an order becomes a trade."},"investing":{"title":"Investing & Wealth Building","level":"beginner","time":"8 lessons","summary":"Set goals, understand your time horizon, diversify, and let compounding work over years."},"sip-mutual-funds":{"title":"SIP & Mutual Funds","level":"beginner","time":"7 lessons","summary":"How a Systematic Investment Plan works, what NAV means, and how to read fund costs.","sections":[{"h":"What is a SIP?","p":"A SIP (Systematic Investment Plan) invests a fixed amount into a mutual fund at regular intervals, usually monthly. When prices are low you get more units, and when prices are high you get fewer. This is called rupee cost averaging. It does not guarantee a profit."},{"h":"NAV and units","p":"NAV (Net Asset Value) is the value of one unit of a mutual fund. It is calculated once a day after the market closes. Your units equal the amount invested divided by that day's NAV.","ul":["Example: if you invest ₹5,000 and the NAV is ₹50, you receive 100 units."]},{"h":"Fund types and costs","ul":["Equity funds invest mainly in shares. Risk and potential return are both higher.","Debt funds invest in bonds. Their price movements are usually smaller.","Index funds copy an index such as NIFTY 50 and usually have low costs.","The expense ratio is the yearly fee a fund charges. All else equal, lower is better."]}]},"reading-charts":{"title":"Reading Charts","level":"beginner","time":"6 lessons","summary":"Understand line, bar and candlestick charts, OHLC data, and volume."},"fundamental-analysis":{"title":"Fundamental Analysis","level":"intermediate","time":"9 lessons","summary":"Evaluate a business using its financial statements, key ratios and quality checks."},"technical-analysis":{"title":"Technical Analysis","level":"intermediate","time":"10 lessons","summary":"Study price and volume patterns, trends, support, resistance and common indicators."},"swing-trading":{"title":"Swing Trading","level":"intermediate","time":"8 lessons","summary":"Hold trades for days to weeks using clear setups, entry and exit rules, and a trade journal."},"risk-management":{"title":"Risk Management","level":"intermediate","time":"7 lessons","summary":"Protect your capital with position sizing, stop losses, exposure limits and a drawdown plan."},"intraday-trading":{"title":"Intraday Trading","level":"advanced","time":"9 lessons","summary":"Trade within one session. Understand liquidity, order execution, margin and the real risks."},"futures-options":{"title":"Futures & Options","level":"advanced","time":"12 lessons","summary":"Understand futures, call and put options, strike price, expiry, margin and payoff, along with their risks."},"option-greeks":{"title":"Option Greeks & Strategies","level":"advanced","time":"10 lessons","summary":"Measure how option prices respond to price, time and volatility, and build defined-risk strategies."},"trading-psychology":{"title":"Trading Psychology","level":"advanced","time":"6 lessons","summary":"Recognise biases such as fear, greed and overtrading, and build a disciplined process."},"candlestick-patterns":{"title":"Candlestick and Chart Patterns","level":"intermediate","time":"25 patterns","summary":"Learn what each candle and chart shape signals, when it matters, how to confirm it, and the mistake to avoid."},"technical-indicators":{"title":"Technical Indicators","level":"intermediate","time":"10 indicators","summary":"Understand what moving averages, RSI, MACD, volume and other indicators measure, when to use each one, and how to use them in a trade."},"tax-basics":{"title":"Tax Basics for Indian Investors and Traders","level":"intermediate","time":"11 topics","summary":"How gains from shares, mutual funds, intraday and F&O are taxed in India, what records to keep, and where to verify the current rules."},"balance-sheet":{"title":"How to Read a Balance Sheet","level":"intermediate","time":"13 topics","summary":"What a balance sheet shows, how to read assets, liabilities and equity, and the ratios that reveal financial strength."},"cash-flow-statement":{"title":"How to Read a Cash Flow Statement","level":"intermediate","time":"13 topics","summary":"Where a company's real cash comes from and goes, and why cash flow can tell you more than profit."},"quarterly-results":{"title":"How to Read Quarterly Results","level":"intermediate","time":"13 topics","summary":"How to read the numbers in a quarterly results filing, compare them correctly, and spot one-off items."},"annual-report":{"title":"How to Read an Annual Report","level":"intermediate","time":"13 topics","summary":"The parts of a company's annual report, what each section tells you, and the warning signs to look for."},"shareholding-pattern":{"title":"Shareholding Pattern and Promoter Holding","level":"intermediate","time":"12 topics","summary":"Who owns a company, how promoter, institutional and public holdings change, and what pledged shares mean."},"valuation-basics":{"title":"Valuation Basics: What Is a Share Worth?","level":"advanced","time":"8 topics","summary":"P/E, P/B, EV/EBITDA, PEG and discounted cash flow explained, with their limits and how to combine them."},"corporate-actions":{"title":"Corporate Actions: Dividends, Bonus, Splits, Rights and Buybacks","level":"intermediate","time":"13 topics","summary":"What companies do with shares and cash, how each action changes the price and your holding, and how to avoid confusion on the ex-date."},"market-rules":{"title":"Market Rules & Investor Protection","level":"beginner","time":"10 topics","summary":"Market timings, settlement, price bands and circuit breakers, applying for IPOs, spotting scams and tips, and how to complain if something goes wrong."}},"hi":{"foundations":{"title":"शेयर बाज़ार की मूल बातें","level":"beginner","time":"6 पाठ","summary":"शेयर क्या है, एक्सचेंज कैसे काम करते हैं, और ऑर्डर ट्रेड में कैसे बदलता है।"},"investing":{"title":"निवेश और धन निर्माण","level":"beginner","time":"8 पाठ","summary":"लक्ष्य तय करें, समय-सीमा समझें, विविधीकरण करें और चक्रवृद्धि को वर्षों तक काम करने दें।"},"sip-mutual-funds":{"title":"SIP और म्यूचुअल फंड","level":"beginner","time":"7 पाठ","summary":"SIP कैसे काम करता है, NAV का मतलब क्या है, और फंड की लागत कैसे पढ़ें।","sections":[{"h":"SIP क्या है?","p":"SIP (Systematic Investment Plan) में एक तय राशि नियमित अंतराल पर, आमतौर पर हर महीने, म्यूचुअल फंड में लगाई जाती है। कीमत कम होने पर ज़्यादा यूनिट और ज़्यादा होने पर कम यूनिट मिलती हैं। इसे रुपी कॉस्ट एवरेजिंग कहते हैं। यह मुनाफ़े की गारंटी नहीं देता।"},{"h":"NAV और यूनिट","p":"NAV (Net Asset Value) म्यूचुअल फंड की एक यूनिट की कीमत है, जो हर दिन बाज़ार बंद होने के बाद तय होती है। आपकी यूनिट = लगाई गई राशि ÷ उस दिन का NAV।","ul":["उदाहरण: ₹5,000 लगाए और NAV ₹50 है, तो आपको 100 यूनिट मिलेंगी।"]},{"h":"फंड के प्रकार और लागत","ul":["इक्विटी फंड मुख्य रूप से शेयरों में निवेश करते हैं। जोखिम और संभावित रिटर्न दोनों अधिक होते हैं।","डेट फंड बॉन्ड में निवेश करते हैं। उनकी कीमत में उतार-चढ़ाव आमतौर पर कम होता है।","इंडेक्स फंड NIFTY 50 जैसे इंडेक्स की नकल करते हैं और अक्सर लागत कम होती है।","एक्सपेंस रेशियो फंड की सालाना फ़ीस है। बाक़ी बातें समान हों तो कम बेहतर है।"]}]},"reading-charts":{"title":"चार्ट कैसे पढ़ें","level":"beginner","time":"6 पाठ","summary":"लाइन, बार और कैंडलस्टिक चार्ट, OHLC डेटा और वॉल्यूम समझें।"},"fundamental-analysis":{"title":"फंडामेंटल एनालिसिस","level":"intermediate","time":"9 पाठ","summary":"वित्तीय विवरण, प्रमुख अनुपात और गुणवत्ता जाँच से किसी कारोबार का मूल्यांकन करें।"},"technical-analysis":{"title":"टेक्निकल एनालिसिस","level":"intermediate","time":"10 पाठ","summary":"कीमत और वॉल्यूम पैटर्न, ट्रेंड, सपोर्ट, रेज़िस्टेंस और आम इंडिकेटर पढ़ें।"},"swing-trading":{"title":"स्विंग ट्रेडिंग","level":"intermediate","time":"8 पाठ","summary":"साफ़ सेटअप, एंट्री-एग्ज़िट नियम और ट्रेड जर्नल से कुछ दिनों से कुछ हफ़्तों तक ट्रेड रखें।"},"risk-management":{"title":"जोखिम प्रबंधन","level":"intermediate","time":"7 पाठ","summary":"पोज़िशन साइज़, स्टॉप लॉस, एक्सपोज़र सीमा और ड्रॉडाउन योजना से पूँजी की रक्षा करें।"},"intraday-trading":{"title":"इंट्राडे ट्रेडिंग","level":"advanced","time":"9 पाठ","summary":"एक ही सत्र में ट्रेड करें। लिक्विडिटी, ऑर्डर निष्पादन, मार्जिन और असली जोखिम समझें।"},"futures-options":{"title":"फ्यूचर्स और ऑप्शंस (F&O)","level":"advanced","time":"12 पाठ","summary":"फ्यूचर्स, कॉल और पुट ऑप्शंस, स्ट्राइक, एक्सपायरी, मार्जिन और पेऑफ़ को उनके जोखिमों के साथ समझें।"},"option-greeks":{"title":"ऑप्शन ग्रीक्स और रणनीतियाँ","level":"advanced","time":"10 पाठ","summary":"कीमत, समय और अस्थिरता के साथ ऑप्शन की कीमत कैसे बदलती है, यह समझें और सीमित-जोखिम रणनीतियाँ बनाएँ।"},"trading-psychology":{"title":"ट्रेडिंग मनोविज्ञान","level":"advanced","time":"6 पाठ","summary":"डर, लालच और ओवरट्रेडिंग जैसे पूर्वाग्रह पहचानें और अनुशासित प्रक्रिया बनाएँ।"},"candlestick-patterns":{"title":"कैंडलस्टिक और चार्ट पैटर्न","level":"intermediate","time":"25 पैटर्न","summary":"हर कैंडल और चार्ट आकार का संकेत, उसका महत्व, पुष्टि कैसे करें, और कौन सी गलती से बचें, यह सीखें।"},"technical-indicators":{"title":"टेक्निकल इंडिकेटर","level":"intermediate","time":"10 इंडिकेटर","summary":"मूविंग एवरेज, RSI, MACD, वॉल्यूम और अन्य इंडिकेटर क्या मापते हैं, हर एक कब इस्तेमाल करें, और ट्रेड में कैसे इस्तेमाल करें, यह समझें।"},"tax-basics":{"title":"भारतीय निवेशकों और ट्रेडरों के लिए टैक्स बेसिक्स","level":"intermediate","time":"11 विषय","summary":"भारत में शेयर, म्यूचुअल फंड, इंट्राडे और F&O से होने वाले लाभ पर टैक्स कैसे लगता है, कौन से रिकॉर्ड रखें, और मौजूदा नियम कहाँ जाँचें।"},"balance-sheet":{"title":"बैलेंस शीट कैसे पढ़ें","level":"intermediate","time":"13 विषय","summary":"बैलेंस शीट क्या दिखाती है, संपत्ति, देनदारी और इक्विटी कैसे पढ़ें, और वित्तीय मज़बूती बताने वाले अनुपात।"},"cash-flow-statement":{"title":"कैश फ़्लो स्टेटमेंट कैसे पढ़ें","level":"intermediate","time":"13 विषय","summary":"कंपनी का असली नकद कहाँ से आता और कहाँ जाता है, और कैश फ़्लो मुनाफ़े से ज़्यादा क्या बताता है।"},"quarterly-results":{"title":"तिमाही नतीजे कैसे पढ़ें","level":"intermediate","time":"13 विषय","summary":"तिमाही नतीजों के आँकड़े कैसे पढ़ें, सही तुलना कैसे करें, और एक-बार की मदों को कैसे पहचानें।"},"annual-report":{"title":"सालाना रिपोर्ट कैसे पढ़ें","level":"intermediate","time":"13 विषय","summary":"कंपनी की सालाना रिपोर्ट के हिस्से, हर हिस्सा क्या बताता है, और चेतावनी के संकेत।"},"shareholding-pattern":{"title":"शेयरहोल्डिंग पैटर्न और प्रमोटर होल्डिंग","level":"intermediate","time":"12 विषय","summary":"कंपनी का मालिक कौन है, प्रमोटर, संस्थागत और सार्वजनिक होल्डिंग कैसे बदलती है, और गिरवी शेयरों का क्या मतलब है।"},"valuation-basics":{"title":"वैल्यूएशन की मूल बातें: शेयर की क़ीमत क्या होनी चाहिए?","level":"advanced","time":"8 विषय","summary":"P/E, P/B, EV/EBITDA, PEG और डिस्काउंटेड कैश फ़्लो समझाए गए, उनकी सीमाओं के साथ और उन्हें मिलाकर कैसे इस्तेमाल करें।"},"corporate-actions":{"title":"कॉर्पोरेट एक्शन: डिविडेंड, बोनस, स्प्लिट, राइट्स और बायबैक","level":"intermediate","time":"13 विषय","summary":"कंपनियाँ शेयर और नकद के साथ क्या करती हैं, हर एक्शन कीमत और आपकी होल्डिंग को कैसे बदलता है, और एक्स-डेट पर भ्रम से कैसे बचें।"},"market-rules":{"title":"बाज़ार के नियम और निवेशक सुरक्षा","level":"beginner","time":"10 विषय","summary":"बाज़ार का समय, सेटलमेंट, प्राइस बैंड और सर्किट ब्रेकर, IPO में आवेदन, धोखाधड़ी और टिप्स पहचानना, और कुछ गलत होने पर शिकायत कैसे करें।"}}};
const LESSON_OVERRIDES = {"en":{"sip-mutual-funds":{"sections":[{"h":"1. What a mutual fund is","p":"A mutual fund pools money from many investors and invests it in a portfolio of securities, such as shares, bonds or both. A professional fund manager makes the investment decisions according to the fund's stated objective. You own units of the fund, and each unit represents a share of the whole portfolio.","ul":["Advantages: diversification with a small amount, professional management, easy to start, and the option to invest regularly.","Limitations: you pay fees, you do not choose individual securities, and the fund can still lose value.","Regulation: mutual funds in India are regulated by SEBI and sold through registered distributors or directly."]},{"h":"2. How a SIP works","p":"A SIP (Systematic Investment Plan) invests a fixed amount at regular intervals, usually monthly, into the scheme you choose. The amount is deducted from your bank account on the chosen date, and units are allotted at that day's NAV. Starting small is possible; many schemes accept small monthly amounts.","ul":["Choose the amount, frequency (monthly is common), the date and the fund.","Set the mandate with your bank or the fund platform, following the approval process they give you.","Keep the SIP running through good and bad markets for the habit and for rupee cost averaging.","You can pause, stop or change the amount. Check any exit load or lock-in before stopping."]},{"h":"3. NAV and units, with the arithmetic","p":"NAV (net asset value) is the value of one unit. It is calculated at the end of each business day, based on the market value of the fund's holdings minus its liabilities, divided by the number of units. The number of units you get equals the amount invested divided by the NAV on the allotment day.","p2":"Example: you invest ₹5,000 on a day when NAV is ₹50. You get 100 units. If NAV is ₹40 the next month, your ₹5,000 buys 125 units. The NAV level itself does not show whether a fund is good; returns and costs matter."},{"h":"4. Rupee cost averaging, explained with numbers","p":"Because the same amount buys more units when NAV is low, your average cost per unit tends to be lower than the average NAV over the period. It is a way of investing that reduces the impact of buying at one high point. It does not guarantee profit, and it works only if the fund recovers or grows.","p2":"Example: NAVs of ₹50, ₹40 and ₹60 over three months with ₹5,000 each. Units: 100 + 125 + 83.33 = 308.33. Total invested ₹15,000. Average cost = ₹15,000 ÷ 308.33 ≈ ₹48.65, lower than the simple average NAV of ₹50."},{"h":"5. Types of mutual funds","ul":["Equity funds: invest mainly in shares. Higher potential return and higher volatility. Includes large-cap, mid-cap, small-cap, flexi-cap and thematic funds.","Index funds and ETFs: copy an index such as NIFTY 50. Lower cost, no active stock picking.","Debt funds: invest in bonds and money-market instruments. Generally lower volatility, but still carry interest-rate and credit risk.","Hybrid funds: mix equity and debt, for example balanced advantage funds.","ELSS (Equity Linked Savings Scheme): equity funds with a 3-year lock-in. Check the current tax-saving rules before choosing one for that purpose."]},{"h":"6. Costs: expense ratio, exit load and taxes","p":"Costs reduce what you keep. Compare them before you choose a fund.","ul":["Expense ratio: the yearly fee the fund charges, as a percentage of assets. It is deducted from the fund's value, so you see it in the NAV.","Exit load: a fee if you redeem before a set period, for example 1% if sold within one year. Check the scheme document.","Direct and regular plans: both invest in the same portfolio. Direct plans have a lower expense ratio because they have no distributor commission.","Tax on gains: equity fund gains are taxed as shares. Debt fund rules differ. See the tax module for the current rules."],"p2":"Example: on ₹10 lakh held for one year, a 2% expense ratio costs about ₹20,000, and 0.2% costs about ₹2,000. The difference compounds over years."},{"h":"7. The mutual fund factsheet","p":"Every scheme publishes a factsheet each month. Learn to read it before you invest.","ul":["Investment objective: what the fund is trying to do. It should match your goal.","Portfolio: the top holdings and the sector split. Check that it matches the description.","Returns over 1, 3, 5 years and since inception, compared with its benchmark index.","Risk measures such as standard deviation or the largest fall (drawdown) shown in the factsheet.","Fund manager name and experience, and the expense ratio."]},{"h":"8. Choosing a fund: a simple process","ul":["Match the fund category to your goal and time frame.","Check the long-term record against its benchmark, not only the best year.","Prefer lower costs when two funds are similar in strategy.","Avoid holding many funds with the same holdings. Check overlap.","Keep the number of funds small. Three to five well-chosen schemes are often enough for a beginner."]},{"h":"9. Stopping, pausing and redeeming","p":"You can change or stop a SIP at any time, but check exit loads and tax before redeeming. Stopping during a fall locks in the loss and stops you buying cheap units. If the fund no longer matches your goal or its mandate has changed, switching may be sensible, but plan the tax effect first."},{"h":"10. Common SIP mistakes","ul":["Stopping the SIP when markets fall, which is when the next units are cheapest.","Starting too many SIPs in similar funds.","Judging a fund only by its NAV or by one year's return.","Expecting a fixed return from an equity SIP.","Ignoring the expense ratio and exit load."]}]}},"hi":{"sip-mutual-funds":{"sections":[{"h":"1. म्यूचुअल फंड क्या है?","p":"म्यूचुअल फंड कई निवेशकों का पैसा इकट्ठा करके शेयर, बॉन्ड या दोनों के पोर्टफ़ोलियो में लगाता है। एक पेशेवर फंड मैनेजर फंड के घोषित उद्देश्य के अनुसार निवेश के फ़ैसले लेता है। आप फंड की यूनिट रखते हैं, और हर यूनिट पूरे पोर्टफ़ोलियो का एक हिस्सा दर्शाती है।","ul":["फ़ायदे: थोड़ी रकम से विविधीकरण, पेशेवर प्रबंधन, शुरू करना आसान, और नियमित निवेश का विकल्प।","सीमाएँ: शुल्क लगते हैं, आप अलग-अलग प्रतिभूतियाँ नहीं चुनते, और फंड की वैल्यू भी गिर सकती है।","नियमन: भारत में म्यूचुअल फंड SEBI द्वारा नियंत्रित हैं और पंजीकृत वितरकों या सीधे बेचे जाते हैं।"]},{"h":"2. SIP कैसे काम करती है","p":"SIP (Systematic Investment Plan) चुनी गई योजना में तय राशि नियमित अंतराल पर, आमतौर पर हर महीने, लगाती है। तय तारीख़ पर राशि बैंक खाते से कटती है और उस दिन के NAV पर यूनिट मिलती हैं। कई योजनाएँ छोटी मासिक राशि भी स्वीकार करती हैं।","ul":["राशि, आवृत्ति (आमतौर पर मासिक), तारीख़ और फंड चुनें।","बैंक या फंड प्लेटफ़ॉर्म के ज़रिए ऑटो-डेबिट की मंज़ूरी उनकी प्रक्रिया के अनुसार दें।","अच्छे और बुरे बाज़ार, दोनों में SIP चलने दें। इससे आदत बनती है और रुपी कॉस्ट एवरेजिंग मिलती है।","SIP रोक, बंद या राशि बदल सकते हैं। रोकने से पहले एग्ज़िट लोड और लॉक-इन देखें।"]},{"h":"3. NAV और यूनिट, अंकगणित के साथ","p":"NAV (नेट एसेट वैल्यू) एक यूनिट का मूल्य है। यह हर कार्यदिवस के अंत में फंड की होल्डिंग की बाज़ार वैल्यू में से देनदारियाँ घटाकर, यूनिट की संख्या से भाग देकर तय होता है। आपको मिलने वाली यूनिट = लगाई गई राशि ÷ आवंटन दिन का NAV।","p2":"उदाहरण: जब NAV ₹50 है तब ₹5,000 लगाए, तो 100 यूनिट मिलीं। अगले महीने NAV ₹40 है, तो ₹5,000 से 125 यूनिट मिलेंगी। NAV का स्तर अपने आप नहीं बताता कि फंड अच्छा है; रिटर्न और लागत मायने रखते हैं।"},{"h":"4. रुपी कॉस्ट एवरेजिंग, संख्याओं के साथ","p":"चूँकि NAV कम होने पर वही राशि ज़्यादा यूनिट देती है, आपकी प्रति यूनिट औसत लागत आमतौर पर उस अवधि के औसत NAV से कम रहती है। यह एक ऊँची कीमत पर एक बार में पूरी रकम लगाने का असर घटाने का तरीका है। यह मुनाफ़े की गारंटी नहीं देता, और तभी काम करता है जब फंड आगे बढ़े।","p2":"उदाहरण: तीन महीने में NAV ₹50, ₹40 और ₹60, हर महीने ₹5,000। यूनिट: 100 + 125 + 83.33 = 308.33। कुल निवेश ₹15,000। औसत लागत = ₹15,000 ÷ 308.33 ≈ ₹48.65, जो सरल औसत NAV ₹50 से कम है।"},{"h":"5. म्यूचुअल फंड के प्रकार","ul":["इक्विटी फंड: मुख्य रूप से शेयरों में। ज़्यादा संभावित रिटर्न और ज़्यादा उतार-चढ़ाव। इसमें लार्ज-कैप, मिड-कैप, स्मॉल-कैप, फ़्लेक्सी-कैप और थीमैटिक फंड आते हैं।","इंडेक्स फंड और ETF: NIFTY 50 जैसे इंडेक्स की नकल। कम लागत, कोई सक्रिय शेयर चयन नहीं।","डेट फंड: बॉन्ड और मनी-मार्केट साधनों में। आमतौर पर कम उतार-चढ़ाव, पर ब्याज-दर और क्रेडिट जोखिम रहता है।","हाइब्रिड फंड: इक्विटी और डेट का मिश्रण, जैसे बैलेंस्ड एडवांटेज फंड।","ELSS (इक्विटी लिंक्ड सेविंग्स स्कीम): 3 साल के लॉक-इन वाले इक्विटी फंड। कर बचत के लिए चुनने से पहले मौजूदा कर नियम जाँचें।"]},{"h":"6. लागत: एक्सपेंस रेशियो, एग्ज़िट लोड और टैक्स","p":"लागत वह घटाती है जो आप रखते हैं। फंड चुनने से पहले इनकी तुलना करें।","ul":["एक्सपेंस रेशियो: फंड द्वारा परिसंपत्तियों के प्रतिशत के रूप में लिया जाने वाला सालाना शुल्क। यह फंड की वैल्यू से कटता है, इसलिए NAV में दिखता है।","एग्ज़िट लोड: तय अवधि से पहले रिडीम करने पर शुल्क, जैसे एक साल में बेचने पर 1%। योजना दस्तावेज़ में देखें।","डायरेक्ट और रेगुलर प्लान: दोनों एक ही पोर्टफ़ोलियो में निवेश करते हैं। डायरेक्ट में वितरक कमीशन नहीं होता, इसलिए एक्सपेंस रेशियो कम।","लाभ पर टैक्स: इक्विटी फंड के लाभ शेयरों की तरह टैक्स होते हैं। डेट फंड के नियम अलग हैं। मौजूदा नियम टैक्स मॉड्यूल में देखें।"],"p2":"उदाहरण: ₹10 लाख पर एक साल के लिए 2% एक्सपेंस रेशियो लगभग ₹20,000 और 0.2% लगभग ₹2,000 खर्च करता है। यह अंतर सालों में बढ़ता है।"},{"h":"7. म्यूचुअल फंड फ़ैक्टशीट","p":"हर योजना हर महीने फ़ैक्टशीट प्रकाशित करती है। निवेश से पहले उसे पढ़ना सीखें।","ul":["निवेश उद्देश्य: फंड क्या करने की कोशिश कर रहा है। वह आपके लक्ष्य से मेल खाना चाहिए।","पोर्टफ़ोलियो: शीर्ष होल्डिंग और सेक्टर बँटवारा। जाँचें कि वह विवरण से मेल खाता है।","1, 3, 5 साल और शुरू से रिटर्न, अपने बेंचमार्क इंडेक्स से तुलना सहित।","जोखिम मापक जैसे स्टैंडर्ड डेविएशन या सबसे बड़ी गिरावट (ड्रॉडाउन)।","फंड मैनेजर का नाम और अनुभव, और एक्सपेंस रेशियो।"]},{"h":"8. फंड चुनने की सरल प्रक्रिया","ul":["फंड श्रेणी को अपने लक्ष्य और समय-सीमा से मिलाएँ।","केवल सबसे अच्छे साल नहीं, लंबी अवधि के रिकॉर्ड को बेंचमार्क से मिलाकर देखें।","रणनीति में मिलते-जुलते दो फंड हों तो कम लागत वाला चुनें।","एक जैसी होल्डिंग वाले कई फंड न रखें। ओवरलैप जाँचें।","फंड की संख्या कम रखें। शुरुआत के लिए तीन से पाँच अच्छी तरह चुनी योजनाएँ अक्सर काफ़ी हैं।"]},{"h":"9. रोकना, रुकना और रिडीम करना","p":"SIP कभी भी बदल या रोक सकते हैं, पर रिडीम करने से पहले एग्ज़िट लोड और टैक्स जाँचें। गिरावट में रोकने से घाटा पक्का होता है और सस्ती यूनिट मिलना बंद होता है। अगर फंड अब आपके लक्ष्य से मेल नहीं खाता या उसका उद्देश्य बदल गया है, तो बदलना समझदारी हो सकती है, पर टैक्स असर पहले तय करें।"},{"h":"10. आम SIP गलतियाँ","ul":["बाज़ार गिरने पर SIP रोक देना, जबकि अगली यूनिट सबसे सस्ती होती हैं।","एक जैसी योजनाओं में बहुत सारी SIP शुरू करना।","फंड को केवल उसके NAV या एक साल के रिटर्न से परखना।","इक्विटी SIP से निश्चित रिटर्न की उम्मीद करना।","एक्सपेंस रेशियो और एग्ज़िट लोड को अनदेखा करना।"]}]}}};
const LESSON_EXTRAS_EN = {"sip-mutual-funds":{"examples":[{"title":"Rupee cost averaging in action","text":"You invest ₹5,000 each month. NAV goes 50, 40, 60. Units bought: 100, 125, 83.33. Total 308.33 units for ₹15,000, so your average cost is ₹15,000 ÷ 308.33 ≈ ₹48.65, lower than the simple average NAV of ₹50."},{"title":"Projected SIP value","text":"₹5,000 a month for 10 years at an assumed 12% a year gives about ₹11.2 lakh from ₹6 lakh invested. The growth (about ₹5.2 lakh) is only an estimate, because market returns vary."}],"scenarios":[{"title":"Market crashes 25% in month 6","text":"Continuing the SIP buys more units while prices are low, so the average cost falls. Stopping the SIP locks in the loss and misses the recovery. Pausing only makes sense if your income or goals have changed."},{"title":"Choosing between an equity and a debt SIP","text":"A 15-year goal such as retirement suits equity funds, which carry more volatility. A 2-year goal such as a vehicle down payment suits debt funds, where the value is steadier."}],"useCases":["Child's education planning with a monthly SIP that starts when the child is born.","Building the habit of investing automatically, since the money leaves your account before you can spend it.","Step-up SIP: increasing the monthly amount each year as your income grows."],"takeaways":["A SIP is a method of investing; it does not guarantee profit.","NAV is the price per unit, not a measure of how good a fund is. Compare returns and costs.","Lower expense ratios leave more of the return with you.","Match the fund type to your time horizon."],"practice":[{"q":"NAV falls from ₹100 to ₹80. How many units does a ₹4,000 SIP buy at ₹80?","a":"4,000 ÷ 80 = 50 units."},{"q":"On ₹10 lakh held for a year, what is the cost difference between a 2% and a 0.2% expense ratio?","a":"1.8% of ₹10 lakh = ₹18,000 a year, before compounding."},{"q":"Is a fund with a lower NAV cheaper than one with a higher NAV?","a":"Not necessarily. NAV only shows the price per unit. What matters is the return on the fund's holdings and its costs."}]}};
const LESSON_EXTRAS_HI = {"sip-mutual-funds":{"examples":[{"title":"रुपी कॉस्ट एवरेजिंग का असर","text":"आप हर महीने ₹5,000 लगाते हैं। NAV 50, 40, 60 रहता है। ख़रीदी गई यूनिट: 100, 125, 83.33। कुल 308.33 यूनिट ₹15,000 में, यानी औसत लागत ₹15,000 ÷ 308.33 ≈ ₹48.65, जो सरल औसत NAV ₹50 से कम है।"},{"title":"SIP की अनुमानित वैल्यू","text":"₹5,000 हर महीने, 10 साल, मान लिए गए 12% सालाना पर: लगभग ₹11.2 लाख, जबकि लगाई रकम ₹6 लाख है। बढ़त (लगभग ₹5.2 लाख) केवल अनुमान है, क्योंकि बाज़ार का रिटर्न बदलता रहता है।"}],"scenarios":[{"title":"छठे महीने बाज़ार 25% गिरे","text":"SIP जारी रखने से कम कीमत पर ज़्यादा यूनिट मिलती हैं, इसलिए औसत लागत घटती है। SIP बंद करने से घाटा पक्का हो जाता है और रिकवरी छूट जाती है। SIP रोकना तभी समझदारी है जब आपकी आय या लक्ष्य बदल गए हों।"},{"title":"इक्विटी या डेट SIP चुनना","text":"15 साल के लक्ष्य, जैसे रिटायरमेंट, के लिए इक्विटी फंड उपयुक्त हैं, भले ही उनमें उतार-चढ़ाव ज़्यादा हो। 2 साल के लक्ष्य, जैसे गाड़ी की डाउन पेमेंट, के लिए डेट फंड उपयुक्त हैं, क्योंकि उनकी वैल्यू स्थिर रहती है।"}],"useCases":["बच्चे की शिक्षा के लिए मासिक SIP, जो बच्चे के जन्म के समय शुरू हो।","निवेश की आदत बनाना, क्योंकि पैसा खर्च होने से पहले ही खाते से चला जाता है।","स्टेप-अप SIP: आय बढ़ने के साथ हर साल मासिक राशि बढ़ाना।"],"takeaways":["SIP निवेश का एक तरीका है; यह मुनाफ़े की गारंटी नहीं देता।","NAV प्रति यूनिट कीमत है, फंड कितना अच्छा है यह उससे तय नहीं होता। रिटर्न और लागत की तुलना करें।","कम एक्सपेंस रेशियो का मतलब है कि रिटर्न का ज़्यादा हिस्सा आपके पास रहता है।","फंड का प्रकार अपनी समय-सीमा से मिलाएँ।"],"practice":[{"q":"NAV ₹100 से गिरकर ₹80 हो गया। ₹80 पर ₹4,000 की SIP कितनी यूनिट देगी?","a":"4,000 ÷ 80 = 50 यूनिट।"},{"q":"₹10 लाख पर एक साल के लिए, 2% और 0.2% एक्सपेंस रेशियो में लागत का अंतर कितना है?","a":"₹10 लाख का 1.8% = सालाना ₹18,000, चक्रवृद्धि से पहले।"},{"q":"क्या कम NAV वाला फंड ज़्यादा सस्ता होता है?","a":"ज़रूरी नहीं। NAV केवल प्रति यूनिट कीमत दिखाता है। असली बात फंड के निवेश पर रिटर्न और उसकी लागत है।"}]}};
